    13	func TestGoModDeclaresModuleAndGoVersion(t *testing.T) {
    14		data, err := os.ReadFile(moduleRoot + "/go.mod")
    15		if err != nil {
    16			t.Fatalf("read go.mod: %v", err)
    17		}
    18		var module, goVersion string
    19		var requires int
    20		for _, line := range strings.Split(string(data), "\n") {
    21			fields := strings.Fields(line)
    22			if len(fields) == 0 {
    23				continue
    24			}
    25			switch fields[0] {
    26			case "module":
    27				module = fields[1]
    28			case "go":
    29				goVersion = fields[1]
    30			case "require":
    31				requires++
    32			}
    33		}
    34		if module != "ddkstat" {
    35			t.Errorf("module = %q, want %q", module, "ddkstat")
    36		}
    37		var major, minor int
    38		if _, err := fmt.Sscanf(goVersion, "%d.%d", &major, &minor); err != nil {
    39			t.Fatalf("go directive %q is not major.minor: %v", goVersion, err)
    40		}
    41		if major < 1 || (major == 1 && minor < 22) {
    42			t.Errorf("go directive = %q, want 1.22 or newer", goVersion)
    43		}
    44		if requires != 0 {
    45			t.Errorf("found %d require directives, want none", requires)
    46		}
    47	}
