     1	// Package cli parses and validates ddkstat invocations.
     2	//
     3	// ParseArgs performs no I/O and never exits the process.
     4	package cli
     5	
     6	import (
     7		"fmt"
     8		"strings"
     9		"time"
    10	)
    11	
    12	// Options is a validated ddkstat invocation.
    13	type Options struct {
    14		Report  string
    15		Target  string
    16		Since   string
    17		Until   string
    18		LogPath string
    19	}
    20	
    21	// UsageError reports an invocation that does not match the ddkstat command line.
    22	type UsageError struct {
    23		Msg string
    24	}
    25	
    26	func (e *UsageError) Error() string { return e.Msg }
    27	
    28	func usageErrorf(format string, args ...any) error {
    29		return &UsageError{Msg: fmt.Sprintf(format, args...)}
    30	}
    31	
    32	var knownReports = map[string]bool{
    33		"summary":  true,
    34		"commands": true,
    35		"targets":  true,
    36		"models":   true,
    37		"daily":    true,
    38		"failures": true,
    39	}
    40	
    41	// checkDate requires value to be a real calendar date written YYYY-MM-DD. Parsing alone is not
    42	// enough: time.Parse accepts shapes such as 2026-1-5, so the value must also round-trip exactly.
    43	func checkDate(name, value string) error {
    44		parsed, err := time.Parse(dateLayout, value)
    45		if err != nil || parsed.Format(dateLayout) != value {
    46			return usageErrorf("option %s needs a YYYY-MM-DD calendar date, got %q", name, value)
    47		}
    48		return nil
    49	}
    50	
    51	const dateLayout = "2006-01-02"
    52	
    53	// ParseArgs parses the arguments that follow the program name into Options. The order is fixed:
    54	// the report name, then any --target, --since or --until options, then exactly one log path.
    55	// Every failure is a *UsageError.
    56	func ParseArgs(args []string) (Options, error) {
    57		if len(args) == 0 {
    58			return Options{}, usageErrorf("missing report name")
    59		}
    60		if !knownReports[args[0]] {
    61			return Options{}, usageErrorf("unknown report %q", args[0])
    62		}
    63		opts := Options{Report: args[0]}
    64	
    65		i := 1
    66		for ; i < len(args) && strings.HasPrefix(args[i], "--"); i += 2 {
    67			name := args[i]
    68			switch name {
    69			case "--target", "--since", "--until":
    70			default:
    71				return Options{}, usageErrorf("unknown option %q", name)
    72			}
    73			if i+1 >= len(args) {
    74				return Options{}, usageErrorf("option %s needs a value", name)
    75			}
    76			value := args[i+1]
    77			switch name {
    78			case "--target":
    79				opts.Target = value
    80			case "--since":
    81				if err := checkDate(name, value); err != nil {
    82					return Options{}, err
    83				}
    84				opts.Since = value
    85			case "--until":
    86				if err := checkDate(name, value); err != nil {
    87					return Options{}, err
    88				}
    89				opts.Until = value
    90			}
    91		}
    92	
    93		positional := args[i:]
    94		switch len(positional) {
    95		case 0:
    96			return Options{}, usageErrorf("missing log path")
    97		case 1:
    98			opts.LogPath = positional[0]
    99			return opts, nil
   100		default:
   101			return Options{}, usageErrorf("unexpected argument %q", positional[1])
   102		}
   103	}
=== internal/cli/run.go
     1	package cli
     2	
     3	import (
     4		"bytes"
     5		"fmt"
     6		"io"
     7		"os"
     8	
     9		"ddkstat/internal/filter"
    10		"ddkstat/internal/logread"
    11	)
    12	
    13	// ReportWriter writes one report for records already narrowed by the filters. skipped is the
    14	// whole-file count of lines that logread did not keep.
    15	type ReportWriter func(w io.Writer, records []logread.Record, skipped int) error
    16	
    17	// writers maps a report name to the writer that a report story registered for it.
    18	var writers = map[string]ReportWriter{}
    19	
    20	// Register makes fn the writer for the report called name. Each report story calls it once from
    21	// its own package, so Run never imports a report package.
    22	func Register(name string, fn ReportWriter) {
    23		writers[name] = fn
    24	}
    25	
    26	// Run executes one ddkstat invocation. args are the arguments that follow the program name. It
    27	// returns the process exit code: 0 on success, 1 when the log cannot be read or a report writer
    28	// fails, and 2 on a usage error. Run never calls os.Exit; only cmd/ddkstat does.
    29	//
    30	// Report output is buffered and written to stdout only when the writer succeeds. Diagnostics go to
    31	// stderr, and skipped log lines never change the exit code.
    32	func Run(args []string, stdout, stderr io.Writer) int {
    33		opts, err := ParseArgs(args)
    34		if err != nil {
    35			fmt.Fprintf(stderr, "usage: ddkstat {summary|commands|targets|models|daily|failures} [--target NAME] [--since DATE] [--until DATE] LOG\n")
    36			return 2
    37		}
    38	
    39		f, err := os.Open(opts.LogPath)
    40		if err != nil {
    41			fmt.Fprintf(stderr, "error: cannot open log %s: %v\n", opts.LogPath, err)
    42			return 1
    43		}
    44		defer f.Close()
    45	
    46		res, err := logread.Read(f, stderr)
    47		if err != nil {
    48			fmt.Fprintf(stderr, "error: cannot read log %s: %v\n", opts.LogPath, err)
    49			return 1
    50		}
    51	
    52		records := filter.ByDateRange(filter.ByTarget(res.Records, opts.Target), opts.Since, opts.Until)
    53	
    54		write, ok := writers[opts.Report]
    55		if !ok {
    56			return 0
    57		}
    58	
    59		var buf bytes.Buffer
    60		if err := write(&buf, records, res.Skipped); err != nil {
    61			fmt.Fprintf(stderr, "error: cannot write %s report: %v\n", opts.Report, err)
    62			return 1
    63		}
    64		if _, err := buf.WriteTo(stdout); err != nil {
    65			fmt.Fprintf(stderr, "error: cannot write report to stdout: %v\n", err)
    66			return 1
    67		}
    68		return 0
    69	}
