=== internal/filter/filter.go
     1	// Package filter narrows a slice of logread.Record by Target and by start date.
     2	//
     3	// Every function here is pure: it performs no I/O, keeps no global state, and never modifies its
     4	// input slice. Input order is preserved.
     5	package filter
     6	
     7	import "ddkstat/internal/logread"
     8	
     9	// ByTarget returns the records whose Target equals name exactly. Comparison is case-sensitive.
    10	// An empty name means no --target was given, so every record is returned. A name that matches no
    11	// record yields an empty slice, never an error.
    12	func ByTarget(records []logread.Record, name string) []logread.Record {
    13		out := make([]logread.Record, 0, len(records))
    14		for _, rec := range records {
    15			if name == "" || rec.Target == name {
    16				out = append(out, rec)
    17			}
    18		}
    19		return out
    20	}
    21	
    22	// ByDateRange returns the records whose Date lies within the inclusive range [since, until].
    23	// Dates are validated YYYY-MM-DD text, so string comparison orders them correctly. An empty bound
    24	// is unset and does not restrict. When since is later than until the result is empty; that is not
    25	// an error.
    26	func ByDateRange(records []logread.Record, since, until string) []logread.Record {
    27		out := make([]logread.Record, 0, len(records))
    28		for _, rec := range records {
    29			if since != "" && rec.Date < since {
    30				continue
    31			}
    32			if until != "" && rec.Date > until {
    33				continue
    34			}
    35			out = append(out, rec)
    36		}
    37		return out
    38	}
=== internal/format/format.go
     1	// Package format holds the shared text formatters for minutes and cost columns.
     2	//
     3	// Every report that prints a minutes or cost column uses these functions, so the rounding rule
     4	// lives in exactly one place. Both functions are pure: they take no filters, read no input and
     5	// keep no state.
     6	package format
     7	
     8	import "fmt"
     9	
    10	// Minutes renders a duration in milliseconds as tenths of a minute with one decimal digit. The
    11	// duration is rounded to the nearest tenth using t = (ms + 3000) / 6000 in integer division, so
    12	// 95000 ms gives "1.6" and 0 ms gives "0.0".
    13	func Minutes(ms int64) string {
    14		t := (ms + 3000) / 6000
    15		return fmt.Sprintf("%d.%d", t/10, t%10)
    16	}
    17	
    18	// Cost renders a US-dollar amount with exactly four decimal places, so 0 gives "0.0000".
    19	func Cost(usd float64) string {
    20		return fmt.Sprintf("%.4f", usd)
    21	}
=== internal/logread/logread.go
     1	// Package logread reads Drydock's JSON Lines LLM execution log into Records.
     2	//
     3	// It never writes to the log it reads. Blank lines are ignored; malformed, incomplete and
     4	// duplicate lines are skipped with a diagnostic on the warning writer.
     5	package logread
     6	
     7	import (
     8		"bufio"
     9		"bytes"
    10		"encoding/json"
    11		"errors"
    12		"fmt"
    13		"io"
    14	)
    15	
    16	// Record is one execution from the log, normalized for reporting.
    17	type Record struct {
    18		ExecutionID    string
    19		StartedAt      string
    20		Date           string
    21		Status         string
    22		Failed         bool
    23		Command        string
    24		Target         string
    25		Provider       string
    26		RequestedModel string
    27		Model          string
    28		InputTokens    int64
    29		CachedTokens   int64
    30		OutputTokens   int64
    31		CostUSD        float64
    32		ElapsedMS      int64
    33		ReturnCode     *int
    34		TimedOut       bool
    35	}
    36	
    37	// Skip describes one physical line that Read did not keep.
    38	type Skip struct {
    39		Line   int    // 1-based physical line number, counting blank lines
    40		Reason string // why the line was skipped
    41	}
    42	
    43	// Result is what Read produced from a log: the decoded records and the skipped lines.
    44	type Result struct {
    45		Records []Record
    46		Skipped int
    47		Skips   []Skip
    48	}
    49	
    50	// wireLine mirrors one JSON Lines object. The required string fields are typed so that a wrong
    51	// type skips the line. Every other field is kept raw and decoded leniently by parseLine, so a
    52	// value of the wrong JSON type never costs the whole line.
    53	type wireLine struct {
    54		ExecutionID string `json:"execution_id"`
    55		StartedAt   string `json:"started_at"`
    56		Status      string `json:"status"`
    57		Job         struct {
    58			CommandName string          `json:"command_name"`
    59			Target      string          `json:"target"`
    60			LLM         json.RawMessage `json:"llm"`
    61			Model       json.RawMessage `json:"model"`
    62		} `json:"job"`
    63		Result json.RawMessage `json:"result"`
    64	}
    65	
    66	// wireResult mirrors the result object. Each member is raw; see wireLine.
    67	type wireResult struct {
    68		ReturnCode json.RawMessage `json:"returncode"`
    69		TimedOut   json.RawMessage `json:"timed_out"`
    70		Stats      json.RawMessage `json:"stats"`
    71	}
    72	
    73	// wireStats mirrors the result.stats object. Each member is raw; see wireLine.
    74	type wireStats struct {
    75		CachedInputTokens json.RawMessage `json:"cached_input_tokens"`
    76		ElapsedMS         json.RawMessage `json:"elapsed_ms"`
    77		InputTokens       json.RawMessage `json:"input_tokens"`
    78		OutputTokens      json.RawMessage `json:"output_tokens"`
    79		CostUSD           json.RawMessage `json:"cost_usd"`
    80		Model             json.RawMessage `json:"model"`
    81	}
    82	
    83	// Read decodes every non-blank line of r as one log record. Malformed, incomplete and duplicate
    84	// lines are counted in Result.Skipped, listed in Result.Skips and described on warn. A duplicate
    85	// is a later line whose execution_id an earlier kept line already registered. The error is non-nil
    86	// only when reading from r fails.
    87	func Read(r io.Reader, warn io.Writer) (Result, error) {
    88		if warn == nil {
    89			warn = io.Discard
    90		}
    91		var res Result
    92		seen := make(map[string]bool)
    93		br := bufio.NewReader(r)
    94		for lineNo := 1; ; lineNo++ {
    95			line, err := br.ReadBytes('\n')
    96			if trimmed := bytes.TrimSpace(line); len(trimmed) > 0 {
    97				rec, perr := parseLine(trimmed)
    98				if perr == nil && seen[rec.ExecutionID] {
    99					perr = errors.New("duplicate execution_id")
   100				}
   101				if perr != nil {
   102					res.Skipped++
   103					res.Skips = append(res.Skips, Skip{Line: lineNo, Reason: perr.Error()})
   104					fmt.Fprintf(warn, "line %d: skipped: %v\n", lineNo, perr)
   105				} else {
   106					seen[rec.ExecutionID] = true
   107					res.Records = append(res.Records, rec)
   108				}
   109			}
   110			if errors.Is(err, io.EOF) {
   111				return res, nil
   112			}
   113			if err != nil {
   114				return res, err
   115			}
   116		}
   117	}
   118	
   119	// parseLine decodes one non-blank, whitespace-trimmed line into a Record. It fails when the line
   120	// is not a JSON object or when a required field is absent, empty or not a string. Every other
   121	// field is optional: an absent, null or wrong-typed value takes its zero value, and a missing
   122	// result or stats object leaves the record with zero numbers.
   123	//
   124	// Model is result.stats.model when that is a non-empty string, otherwise job.model.
   125	func parseLine(data []byte) (Record, error) {
   126		if data[0] != '{' {
   127			return Record{}, errors.New("not a JSON object")
   128		}
   129		var w wireLine
   130		if err := json.Unmarshal(data, &w); err != nil {
   131			return Record{}, err
   132		}
   133		required := []struct{ name, value string }{
   134			{"execution_id", w.ExecutionID},
   135			{"started_at", w.StartedAt},
   136			{"status", w.Status},
   137			{"job.command_name", w.Job.CommandName},
   138			{"job.target", w.Job.Target},
   139		}
   140		for _, field := range required {
   141			if field.value == "" {
   142				return Record{}, fmt.Errorf("missing or empty %s", field.name)
   143			}
   144		}
   145		var res wireResult
   146		decodeObject(w.Result, &res)
   147		var stats wireStats
   148		decodeObject(res.Stats, &stats)
   149	
   150		requested := stringValue(w.Job.Model)
   151		model := stringValue(stats.Model)
   152		if model == "" {
   153			model = requested
   154		}
   155		return Record{
   156			ExecutionID:    w.ExecutionID,
   157			StartedAt:      w.StartedAt,
   158			Date:           firstRunes(w.StartedAt, 10),
   159			Status:         w.Status,
   160			Failed:         w.Status != "succeeded",
   161			Command:        w.Job.CommandName,
   162			Target:         w.Job.Target,
   163			Provider:       stringValue(w.Job.LLM),
   164			RequestedModel: requested,
   165			Model:          model,
   166			InputTokens:    intValue(stats.InputTokens),
   167			CachedTokens:   intValue(stats.CachedInputTokens),
   168			OutputTokens:   intValue(stats.OutputTokens),
   169			CostUSD:        floatValue(stats.CostUSD),
   170			ElapsedMS:      intValue(stats.ElapsedMS),
   171			ReturnCode:     returnCode(res.ReturnCode),
   172			TimedOut:       boolValue(res.TimedOut),
   173		}, nil
   174	}
   175	
   176	// decodeObject decodes raw into v when raw holds a JSON object. Absent, null and non-object values
   177	// leave v at its zero value.
   178	func decodeObject(raw json.RawMessage, v any) {
   179		if len(raw) > 0 {
   180			_ = json.Unmarshal(raw, v)
   181		}
   182	}
   183	
   184	// intValue returns raw as an int64, or zero when raw is absent, null or not an integer.
   185	func intValue(raw json.RawMessage) int64 {
   186		var n int64
   187		_ = json.Unmarshal(raw, &n)
   188		return n
   189	}
   190	
   191	// floatValue returns raw as a float64, or zero when raw is absent, null or not a number.
   192	func floatValue(raw json.RawMessage) float64 {
   193		var f float64
   194		_ = json.Unmarshal(raw, &f)
   195		return f
   196	}
   197	
   198	// stringValue returns raw as a string, or the empty string when raw is absent, null or not a string.
   199	func stringValue(raw json.RawMessage) string {
   200		var s string
   201		_ = json.Unmarshal(raw, &s)
   202		return s
   203	}
   204	
   205	// boolValue returns raw as a bool, or false when raw is absent, null or not a bool.
   206	func boolValue(raw json.RawMessage) bool {
   207		var b bool
   208		_ = json.Unmarshal(raw, &b)
   209		return b
   210	}
   211	
   212	// returnCode returns raw as a return code. It is nil when raw is absent, null or not an integer.
   213	func returnCode(raw json.RawMessage) *int {
   214		var n int
   215		if json.Unmarshal(raw, &n) != nil || string(raw) == "null" {
   216			return nil
   217		}
   218		return &n
   219	}
   220	
   221	// firstRunes returns the first n characters of s, or all of s when it is shorter.
   222	func firstRunes(s string, n int) string {
   223		r := []rune(s)
   224		if len(r) > n {
   225			r = r[:n]
   226		}
   227		return string(r)
   228	}
