     1	// Package cli parses and validates ddkstat invocations.
     2	//
     3	// ParseArgs performs no I/O and never exits the process.
     4	package cli
     5	
     6	import (
     7		"fmt"
     8		"strings"
     9		"time"
    10	)
    11	
    12	// Options is a validated ddkstat invocation.
    13	type Options struct {
    14		Report  string
    15		Target  string
    16		Since   string
    17		Until   string
    18		LogPath string
    19	}
    20	
    21	// UsageError reports an invocation that does not match the ddkstat command line.
    22	type UsageError struct {
    23		Msg string
    24	}
    25	
    26	func (e *UsageError) Error() string { return e.Msg }
    27	
    28	func usageErrorf(format string, args ...any) error {
    29		return &UsageError{Msg: fmt.Sprintf(format, args...)}
    30	}
    31	
    32	var knownReports = map[string]bool{
    33		"summary":  true,
    34		"commands": true,
    35		"targets":  true,
    36		"models":   true,
    37		"daily":    true,
    38		"failures": true,
    39	}
    40	
    41	// checkDate requires value to be a real calendar date written YYYY-MM-DD. Parsing alone is not
    42	// enough: time.Parse accepts shapes such as 2026-1-5, so the value must also round-trip exactly.
    43	func checkDate(name, value string) error {
    44		parsed, err := time.Parse(dateLayout, value)
    45		if err != nil || parsed.Format(dateLayout) != value {
    46			return usageErrorf("option %s needs a YYYY-MM-DD calendar date, got %q", name, value)
    47		}
    48		return nil
    49	}
    50	
    51	const dateLayout = "2006-01-02"
    52	
    53	// ParseArgs parses the arguments that follow the program name into Options. The order is fixed:
    54	// the report name, then any --target, --since or --until options, then exactly one log path.
    55	// Every failure is a *UsageError.
    56	func ParseArgs(args []string) (Options, error) {
    57		if len(args) == 0 {
    58			return Options{}, usageErrorf("missing report name")
    59		}
    60		if !knownReports[args[0]] {
    61			return Options{}, usageErrorf("unknown report %q", args[0])
    62		}
    63		opts := Options{Report: args[0]}
    64	
    65		i := 1
    66		for ; i < len(args) && strings.HasPrefix(args[i], "--"); i += 2 {
    67			name := args[i]
    68			switch name {
    69			case "--target", "--since", "--until":
    70			default:
    71				return Options{}, usageErrorf("unknown option %q", name)
    72			}
    73			if i+1 >= len(args) {
    74				return Options{}, usageErrorf("option %s needs a value", name)
    75			}
    76			value := args[i+1]
    77			switch name {
    78			case "--target":
    79				opts.Target = value
    80			case "--since":
    81				if err := checkDate(name, value); err != nil {
    82					return Options{}, err
    83				}
    84				opts.Since = value
    85			case "--until":
    86				if err := checkDate(name, value); err != nil {
    87					return Options{}, err
    88				}
    89				opts.Until = value
    90			}
    91		}
    92	
    93		positional := args[i:]
    94		switch len(positional) {
    95		case 0:
    96			return Options{}, usageErrorf("missing log path")
    97		case 1:
    98			opts.LogPath = positional[0]
    99			return opts, nil
   100		default:
   101			return Options{}, usageErrorf("unexpected argument %q", positional[1])
   102		}
   103	}
